// Kanban SPA — vanilla JS client for the REST API.
const app = document.getElementById('app');
const msg = document.getElementById('msg');
let token = localStorage.getItem('kanbanToken');
let me = null;

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
function flash(t) { msg.textContent = t || ''; if (t) setTimeout(() => { if (msg.textContent === t) msg.textContent = ''; }, 4000); }

async function api(method, path, body) {
  const res = await fetch(path, {
    method,
    headers: { 'content-type': 'application/json', ...(token ? { authorization: 'Bearer ' + token } : {}) },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  if (res.status === 204) return null;
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    if (res.status === 401 && token && path !== '/api/auth/login') { token = null; localStorage.removeItem('kanbanToken'); route(); }
    throw new Error(data.message || data.error || res.statusText);
  }
  return data;
}

function setHeader() {
  document.getElementById('who').textContent = me ? me.displayName + ' (@' + me.username + ')' : '';
  document.getElementById('logoutBtn').hidden = !me;
}
document.getElementById('logoutBtn').onclick = async () => {
  try { await api('POST', '/api/auth/logout'); } catch {}
  token = null; me = null; localStorage.removeItem('kanbanToken'); location.hash = ''; route();
};

function renderAuth() {
  app.innerHTML = `
  <h2>Log in</h2>
  <form id="loginForm"><input name="username" placeholder="username" required><input name="password" type="password" placeholder="password" required><button>Log in</button></form>
  <h2>Register</h2>
  <form id="regForm"><input name="username" placeholder="username" required><input name="displayName" placeholder="display name"><input name="password" type="password" placeholder="password (8+ chars)" required><button>Register</button></form>`;
  const v = (f) => Object.fromEntries(new FormData(f));
  app.querySelector('#loginForm').onsubmit = async (e) => {
    e.preventDefault();
    try { await login(v(e.target)); } catch (err) { flash(err.message); }
  };
  app.querySelector('#regForm').onsubmit = async (e) => {
    e.preventDefault();
    const d = v(e.target); if (!d.displayName) delete d.displayName;
    try { await api('POST', '/api/auth/register', d); await login(d); } catch (err) { flash(err.message); }
  };
}
async function login({ username, password }) {
  const r = await api('POST', '/api/auth/login', { username, password });
  token = r.token; me = r.user; localStorage.setItem('kanbanToken', token); route();
}

async function renderBoards() {
  const boards = await api('GET', '/api/boards');
  app.innerHTML = `<h2>Your boards</h2>
  <ul class="boards">${boards.map((b) => `<li data-id="${esc(b.id)}">${esc(b.name)} <small>(${esc(b.role)})</small></li>`).join('') || '<li>No boards yet</li>'}</ul>
  <form id="newBoard"><input name="name" placeholder="New board name" required maxlength="100"><input name="description" placeholder="description"><button>Create board</button></form>`;
  app.querySelectorAll('.boards li[data-id]').forEach((li) => (li.onclick = () => (location.hash = '#/board/' + li.dataset.id)));
  app.querySelector('#newBoard').onsubmit = async (e) => {
    e.preventDefault();
    const d = Object.fromEntries(new FormData(e.target));
    try { const b = await api('POST', '/api/boards', d); location.hash = '#/board/' + b.id; } catch (err) { flash(err.message); }
  };
}

async function moveCard(cardId, columnId, position) {
  try { await api('POST', `/api/cards/${cardId}/move`, position === undefined ? { columnId } : { columnId, position }); } catch (err) { flash(err.message); }
  route();
}

async function renderBoard(id) {
  const b = await api('GET', '/api/boards/' + id);
  const role = b.members.find((m) => m.userId === me.id)?.role;
  const canEdit = role === 'owner' || role === 'editor';
  const labels = Object.fromEntries(b.labels.map((l) => [l.id, l]));
  const cols = b.columns;
  app.innerHTML = `<p><a href="#">&larr; Boards</a></p><h2>${esc(b.name)}</h2><p>${esc(b.description)}</p>
  <div class="columns">${cols.map((c, ci) => `
    <section class="column" data-col="${esc(c.id)}">
      <h3>${esc(c.name)} <small>${c.cards.length}${c.wipLimit ? '/' + c.wipLimit : ''}</small></h3>
      ${c.cards.map((k) => `
        <article class="card" draggable="${canEdit}" data-card="${esc(k.id)}">
          <div>${k.labels.map((l) => labels[l] ? `<span class="label" style="background:${esc(labels[l].color)}">${esc(labels[l].name)}</span>` : '').join('')}</div>
          <strong>${esc(k.title)}</strong>${k.dueDate ? `<div><small>Due ${esc(k.dueDate)}</small></div>` : ''}
          ${canEdit ? `<div class="actions">
            ${ci > 0 ? `<button data-move="${esc(cols[ci - 1].id)}" title="Move left">&larr;</button>` : ''}
            ${ci < cols.length - 1 ? `<button data-move="${esc(cols[ci + 1].id)}" title="Move right">&rarr;</button>` : ''}
            <button data-del="1" title="Delete">&times;</button></div>` : ''}
        </article>`).join('')}
      ${canEdit ? `<form class="newCard"><input name="title" placeholder="New card" required maxlength="200"><button>Add</button></form>` : ''}
    </section>`).join('')}
  </div>
  ${canEdit ? `<form id="newCol"><input name="name" placeholder="New column" required><button>Add column</button></form>` : ''}`;

  app.querySelectorAll('.newCard').forEach((f) => (f.onsubmit = async (e) => {
    e.preventDefault();
    const colId = f.closest('.column').dataset.col;
    try { await api('POST', `/api/columns/${colId}/cards`, { title: new FormData(f).get('title') }); route(); } catch (err) { flash(err.message); }
  }));
  const nc = app.querySelector('#newCol');
  if (nc) nc.onsubmit = async (e) => {
    e.preventDefault();
    try { await api('POST', `/api/boards/${id}/columns`, { name: new FormData(nc).get('name') }); route(); } catch (err) { flash(err.message); }
  };
  app.querySelectorAll('[data-move]').forEach((btn) => (btn.onclick = () => moveCard(btn.closest('.card').dataset.card, btn.dataset.move)));
  app.querySelectorAll('[data-del]').forEach((btn) => (btn.onclick = async () => {
    try { await api('DELETE', '/api/cards/' + btn.closest('.card').dataset.card); } catch (err) { flash(err.message); }
    route();
  }));

  // HTML5 drag and drop (pattern per MDN "HTML Drag and Drop API")
  app.querySelectorAll('.card[draggable="true"]').forEach((el) => {
    el.addEventListener('dragstart', (e) => { e.dataTransfer.setData('text/plain', el.dataset.card); e.dataTransfer.effectAllowed = 'move'; });
  });
  app.querySelectorAll('.column').forEach((col) => {
    col.addEventListener('dragover', (e) => { if (canEdit) { e.preventDefault(); col.classList.add('over'); } });
    col.addEventListener('dragleave', () => col.classList.remove('over'));
    col.addEventListener('drop', (e) => {
      e.preventDefault(); col.classList.remove('over');
      const cardId = e.dataTransfer.getData('text/plain');
      if (!cardId) return;
      // compute insert position from pointer Y among the column's other cards
      const others = [...col.querySelectorAll('.card')].filter((c) => c.dataset.card !== cardId);
      let pos = others.findIndex((c) => { const r = c.getBoundingClientRect(); return e.clientY < r.top + r.height / 2; });
      if (pos < 0) pos = others.length;
      moveCard(cardId, col.dataset.col, pos);
    });
  });
}

async function route() {
  flash('');
  if (token && !me) {
    try { me = (await api('GET', '/api/auth/me')).user; } catch { token = null; localStorage.removeItem('kanbanToken'); }
  }
  setHeader();
  if (!token || !me) return renderAuth();
  const m = /^#\/board\/(.+)$/.exec(location.hash);
  try {
    if (m) await renderBoard(decodeURIComponent(m[1]));
    else await renderBoards();
  } catch (err) { flash(err.message); if (m) { location.hash = ''; } }
}
window.addEventListener('hashchange', route);
route();
EOF

